using System;

namespace Bodu.Extensions;

public partial class DateTimeExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.ElapsedTimeSince" />, when FutureTime, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    [DataRow(1, DateTimeKind.Utc)]
    [DataRow(5, DateTimeKind.Local)]
    public void ElapsedTimeSince_WhenFutureTime_ShouldReturnNegativeTimeSpan(int minutesOffset, DateTimeKind kind)
    {
        DateTime future = kind == DateTimeKind.Utc
            ? DateTime.UtcNow.AddMinutes(minutesOffset)
            : DateTime.Now.AddMinutes(minutesOffset);

        future = DateTime.SpecifyKind(future, kind);

        TimeSpan elapsed = future.ElapsedTimeSince();

        Assert.IsTrue(elapsed.TotalMilliseconds < 0, "Elapsed should be negative for future timestamps.");
        Assert.IsTrue(elapsed.TotalMinutes <= -minutesOffset + 0.01,
            $"Expected approx. -{minutesOffset} min but got {elapsed.TotalMinutes:F3} min.");
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.ElapsedTimeSince" />, when KindIsUnspecified, throws <see cref="ArgumentException" />.
    /// </summary>
    [TestMethod]
    public void ElapsedTimeSince_WhenKindIsUnspecified_ShouldThrowExactly()
    {
        DateTime input = DateTime.SpecifyKind(DateTime.UtcNow, DateTimeKind.Unspecified);

        var ex = Assert.ThrowsExactly<ArgumentException>(() =>
        {
            _ = input.ElapsedTimeSince();
        });

        StringAssert.Contains(ex.Message, "Kind");
        StringAssert.Contains(ex.Message, "Utc or Local");
    }

    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.ElapsedTimeSince" />, when Now, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    [DataRow(DateTimeKind.Utc)]
    [DataRow(DateTimeKind.Local)]
    public void ElapsedTimeSince_WhenNow_ShouldReturnNearZero(DateTimeKind kind)
    {
        DateTime anchor = kind == DateTimeKind.Utc ? DateTime.UtcNow : DateTime.Now;
        anchor = DateTime.SpecifyKind(anchor, kind);

        Thread.Sleep(1); // Ensure measurable elapsed time

        TimeSpan elapsed = anchor.ElapsedTimeSince();

        // The elapsed span must be non-negative (the anchor is in the past) and "near zero". A generous upper bound is
        // used deliberately: the measurement spans real wall-clock time, so on a contended CI host thread scheduling
        // or a GC pause can stretch the gap well beyond a few milliseconds. The bound still catches gross defects such
        // as a sign error, a wrong unit, or an incorrect epoch, which would yield negative or minute-scale results.
        Assert.IsTrue(elapsed.TotalMilliseconds >= 0,
            $"Elapsed was {elapsed.TotalMilliseconds:F3}ms, expected a non-negative span.");
        Assert.IsTrue(elapsed.TotalSeconds < 30,
            $"Elapsed was {elapsed.TotalSeconds:F3}s, expected a near-zero span.");
    }
    /// <summary>
    /// Verifies that <see cref="DateTimeExtensions.ElapsedTimeSince" />, when PastTime, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    [DataRow(-5, DateTimeKind.Utc)]
    [DataRow(-10, DateTimeKind.Local)]
    public void ElapsedTimeSince_WhenPastTime_ShouldReturnPositiveTimeSpan(int minutesOffset, DateTimeKind kind)
    {
        DateTime past = kind == DateTimeKind.Utc
            ? DateTime.UtcNow.AddMinutes(minutesOffset)
            : DateTime.Now.AddMinutes(minutesOffset);

        past = DateTime.SpecifyKind(past, kind);

        TimeSpan elapsed = past.ElapsedTimeSince();

        Assert.IsTrue(elapsed.TotalMinutes >= Math.Abs(minutesOffset) - 0.01,
            $"Expected at least {Math.Abs(minutesOffset)} minutes elapsed, got {elapsed.TotalMinutes:F2}");
        Assert.IsTrue(elapsed.TotalMilliseconds > 0, "Elapsed should be positive for past dates.");
    }

}
